16#BY:export function selectTraceEngine(value: string | undefined | null): TraceEngineId {
17#VH:	if (value === undefined || value === null || value.trim() === "") {
18#RH:		return DEFAULT_TRACE_ENGINE_ID;
19#TZ:	}
20#BZ:	if (isTraceEngineId(value)) return value;
21#WZ:	throw new TraceEngineConfigurationError(value);
22#NQ:}

