 45#KQ:	readonly traceEngine: Extract<TraceEngineId, "canonical-v2">;
 46#HN:	readonly contract: "ghostline.api.canonical-v2.v1";
 47#YK:	readonly readActiveMetadata: (
 48#ZR:		sessionId: string,
 49#XP:	) => Promise<ActiveCanonicalV2Metadata | undefined>;
 50#XW:	readonly readEvidence: (
 51#PM:		request: canonicalV2.EvidenceReadRequestDto,
 52#KZ:	) => Promise<canonicalV2.EvidenceReadResponseDto>;
 53#MV:	readonly expandField: (
 54#RJ:		request: canonicalV2.CanonicalFieldExpansionRequest,
