 67#KQ:	readonly traceEngine: Extract<TraceEngineId, "canonical-v2">;
 68#HN:	readonly contract: "ghostline.api.canonical-v2.v1";
 69#WR:	readonly native: CanonicalV2NativeReadBundle;
 70#BY:};
 71#PR:
 72#PH:export function createCanonicalV2RouteBundle(
 73#MZ:	input: TraceEngineRouteBundleInput,
 74#VV:): CanonicalV2TraceRouteBundle {
 75#KV:	const native = Object.freeze({
 76#RH:		traceEngine: "canonical-v2" as const,
 77#JJ:		contract: "ghostline.api.canonical-v2.v1" as const,
 78#XQ:		readActiveMetadata: (sessionId) =>
 79#QZ:			readActiveCanonicalV2Metadata(input.dbClient, sessionId),
 80#YK:		readEvidence: (request) =>
 81#KT:			readCanonicalEvidence(request, {
 82#HM:				artifactRoot: input.artifactRoot,
 83#PW:				repository: createPrismaCanonicalInspectionRepository(input.dbClient),
 84#PX:				resolverRegistry: createEvidenceResolverRegistry(),
 85#TQ:			}),
 86#JY:		expandField: (request) =>
 87#QQ:			expandCanonicalField(request, {
 88#MQ:				loadActiveRecord: (query) => loadCanonicalV2Record(input.dbClient, query),
 89#MZ:			}),
 90#XY:		artifactRoot: input.artifactRoot,
 91#QT:		pathService: input.pathService,
 92#PQ:		cursorSigner: input.cursorSigner,
 93#VN:	}) satisfies CanonicalV2NativeReadBundle;
 94#BJ:	const http = Object.freeze({
 95#RH:		traceEngine: "canonical-v2" as const,
 96#JJ:		contract: "ghostline.api.canonical-v2.v1" as const,
 97#SJ:		native,
 98#XY:	}) satisfies CanonicalV2HttpRouteBundle;
 99#MR:	return Object.freeze({ traceEngine: "canonical-v2", native, http });
100#MN:}
101#ZS:
102#KB:async function loadCanonicalV2Record(
103#VY:	dbClient: ActivateRevisionInput["dbClient"],
104#HW:	query: { readonly sessionId: string; readonly recordId: string },
105#HK:): Promise<
106#QJ:	| { readonly activeRevisionId: string; readonly record: unknown }
107#NB:	| undefined
108#TY:> {
109#VH:	const active = await readActiveCanonicalV2Metadata(dbClient, query.sessionId);
110#PZ:	if (active === undefined) return undefined;
111#JT:	const row = await dbClient.canonicalV2Record.findFirst({
112#SW:		where: {
113#KW:			revisionId: active.activeRevisionId,
114#BH:			sessionId: query.sessionId,
115#PR:			recordId: query.recordId,
116#RM:		},
117#MR:		include: { evidence: { orderBy: { evidenceIndex: "asc" } } },
118#QR:	});
119#RS:	if (row === null) return undefined;
120#XX:	return {
121#TW:		activeRevisionId: active.activeRevisionId,
122#JV:		record: {
123#RZ:			recordId: row.recordId,
124#KV:			sessionId: row.sessionId,
125#RM:			canonicalRevisionId: row.revisionId,
126#JY:			schemaVersion: row.schemaVersion,
127#NK:			rawArtifactId: row.artifactId,
128#ZR:			globalOrdinal: row.globalOrdinal,
129#NT:			...(row.turnId === null ? {} : { turnId: row.turnId }),
130#XT:			...(row.recordedAt === null ? {} : { recordedAt: row.recordedAt }),
131#TB:			...(row.actor === null ? {} : { actor: row.actor }),
132#BT:			kind: row.kind,
133#VW:			payload: JSON.parse(row.payloadJson),
134#VS:			evidence: row.evidence.map((item: { readonly evidenceJson: string }) =>
135#TB:				JSON.parse(item.evidenceJson),
136#ZP:			),
137#BJ:			recordDigest: row.recordDigest,
138#NV:		},
139#SJ:	};
140#HP:}

