 73#KV:	const native = Object.freeze({
 74#QH:		traceEngine: "canonical-v1" as const,
 75#RR:		contract: "ghostline.api.legacy.v1" as const,
 76#WH:	}) satisfies CanonicalV1NativeReadBundle;
 77#BJ:	const http = Object.freeze({
 78#QH:		traceEngine: "canonical-v1" as const,
 79#RR:		contract: "ghostline.api.legacy.v1" as const,
