 83#YX:
 84#PH:export function createCanonicalV2RouteBundle(
 85#MZ:	input: TraceEngineRouteBundleInput,
 86#VV:): CanonicalV2TraceRouteBundle {
 87#KV:	const native = Object.freeze({
 88#RH:		traceEngine: "canonical-v2" as const,
 89#JJ:		contract: "ghostline.api.canonical-v2.v1" as const,
 90#XQ:		readActiveMetadata: (sessionId) =>
 91#QZ:			readActiveCanonicalV2Metadata(input.dbClient, sessionId),
 92#YK:		readEvidence: (request) =>
 93#KT:			readCanonicalEvidence(request, {
 94#HM:				artifactRoot: input.artifactRoot,
 95#PW:				repository: createPrismaCanonicalInspectionRepository(input.dbClient),
 96#PX:				resolverRegistry: createEvidenceResolverRegistry(),
 97#YN:			}),
 98#JY:		expandField: (request) =>
 99#QQ:			expandCanonicalField(request, {
100#MQ:				loadActiveRecord: (query) => loadCanonicalV2Record(input.dbClient, query),
101#TR:			}),
102#XY:		artifactRoot: input.artifactRoot,
103#QT:		pathService: input.pathService,
104#PQ:		cursorSigner: input.cursorSigner,
105#VN:	}) satisfies CanonicalV2NativeReadBundle;
106#BJ:	const http = Object.freeze({
107#RH:		traceEngine: "canonical-v2" as const,
108#JJ:		contract: "ghostline.api.canonical-v2.v1" as const,
109#SJ:		native,
110#XY:	}) satisfies CanonicalV2HttpRouteBundle;
111#MR:	return Object.freeze({ traceEngine: "canonical-v2", native, http });
112#HR:}
113#PP:
114#KB:async function loadCanonicalV2Record(
115#VY:	dbClient: ActivateRevisionInput["dbClient"],
116#HW:	query: { readonly sessionId: string; readonly recordId: string },
117#HK:): Promise<
118#QJ:	| { readonly activeRevisionId: string; readonly record: unknown }
119#NB:	| undefined
120#QN:> {
121#VH:	const active = await readActiveCanonicalV2Metadata(dbClient, query.sessionId);
122#PZ:	if (active === undefined) return undefined;
123#JT:	const row = await dbClient.canonicalV2Record.findFirst({
124#SW:		where: {
125#KW:			revisionId: active.activeRevisionId,
126#BH:			sessionId: query.sessionId,
127#PR:			recordId: query.recordId,
128#WV:		},
129#MR:		include: { evidence: { orderBy: { evidenceIndex: "asc" } } },
130#XY:	});
131#RS:	if (row === null) return undefined;
132#XX:	return {
133#TW:		activeRevisionId: active.activeRevisionId,
134#JV:		record: {
135#RZ:			recordId: row.recordId,
136#KV:			sessionId: row.sessionId,
137#RM:			canonicalRevisionId: row.revisionId,
138#JY:			schemaVersion: row.schemaVersion,
139#NK:			rawArtifactId: row.artifactId,
140#ZR:			globalOrdinal: row.globalOrdinal,
141#NT:			...(row.turnId === null ? {} : { turnId: row.turnId }),
142#XT:			...(row.recordedAt === null ? {} : { recordedAt: row.recordedAt }),
143#TB:			...(row.actor === null ? {} : { actor: row.actor }),
144#BT:			kind: row.kind,
145#VW:			payload: JSON.parse(row.payloadJson),
146#VS:			evidence: row.evidence.map((item: { readonly evidenceJson: string }) =>
147#TB:				JSON.parse(item.evidenceJson),
148#ZP:			),
149#BJ:			recordDigest: row.recordDigest,
150#HS:		},
151#SH:	};
152#QT:}

