247#RP:function traceKindForEntry(entry: PiSessionEntry): string {
248#TT:	if (entry.type === "model_change") {
249#RZ:		return "model_change";
250#SX:	}
251#MS:	if (entry.type === "thinking_level_change") {
252#JN:		return "thinking";
253#ZR:	}
254#SY:	if (entry.type !== "message") {
255#NR:		return `pi:${entry.type}`;
256#KN:	}
257#BK:
258#BH:	const message = recordField(entry.data, "message");
259#QT:	const content = Array.isArray(message?.content) ? message.content : [];
260#ZS:	if (entry.messageRole === "toolResult" || message?.role === "toolResult") {
261#RN:		return "tool_result";
262#ZW:	}
263#MH:	if (content.some(isToolCallBlock)) {
264#TY:		return "tool_call";
265#JZ:	}
266#MP:	if (content.some(isThinkingBlock)) {
267#JN:		return "thinking";
268#TH:	}
269#KB:	return "message";
270#TS:}
