272#TM:function actorForEntry(entry: PiSessionEntry): string | undefined {
273#BH:	const message = recordField(entry.data, "message");
274#TM:	return (
275#VW:		entry.messageRole ??
276#WH:		stringField(message, "role") ??
277#KY:		stringField(entry.data, "role") ??
278#VX:		stringField(entry.data, "actor")
279#SQ:	);
280#NX:}
281#MP:
282#WQ:function correlationIdForEntry(entry: PiSessionEntry): string | undefined {
283#BH:	const message = recordField(entry.data, "message");
284#BM:	if (message?.role === "toolResult") {
285#SS:		return stringField(message, "toolCallId");
286#HQ:	}
287#HB:
288#QT:	const content = Array.isArray(message?.content) ? message.content : [];
289#RH:	const toolCallBlock = content.find(isToolCallBlock);
290#YN:	return toolCallBlock === undefined
291#ZN:		? undefined
292#BM:		: stringField(toolCallBlock, "id");
293#PQ:}
294#YH:
295#RQ:function diagnosticJsonPointer(
296#JK:	diagnostic: PiSessionDiagnostic,
297#YS:): string | undefined {
298#HW:	switch (diagnostic.code) {
299#WN:		case "missing_type":
300#JH:		case "unknown_entry_type":
301#BX:			return "$.type";
302#RJ:		case "missing_id":
303#KB:		case "duplicate_id":
304#JV:			return "$.id";
305#HW:		case "missing_parent":
306#XZ:			return "$.parentId";
307#XP:		case "malformed_json":
308#WH:			return undefined;
309#RB:	}
310#KN:}
