312#BZ:function comparePendingRows(
313#PH:	left: PendingCanonicalTraceRow,
314#WX:	right: PendingCanonicalTraceRow,
315#MN:): number {
316#TM:	return (
317#PJ:		left.sourceLine - right.sourceLine ||
318#JT:		left.kindOrder - right.kindOrder ||
319#VZ:		left.parserOrdinal - right.parserOrdinal
320#TR:	);
321#BJ:}
322#PS:
323#JJ:function isToolCallBlock(value: unknown): value is Record<string, unknown> {
324#WS:	return isRecord(value) && value.type === "toolCall";
325#QY:}
326#MV:
327#XW:function isThinkingBlock(value: unknown): value is Record<string, unknown> {
328#SY:	return isRecord(value) && value.type === "thinking";
329#ZR:}
330#MB:
331#KR:function recordField(
332#NV:	value: Record<string, unknown>,
333#JN:	field: string,
334#PK:): Record<string, unknown> | undefined {
335#RX:	const fieldValue = value[field];
336#VR:	return isRecord(fieldValue) ? fieldValue : undefined;
337#SJ:}
338#XN:
339#WZ:function stringField(
340#BM:	value: Record<string, unknown> | undefined,
341#JN:	field: string,
342#YS:): string | undefined {
343#KW:	const fieldValue = value?.[field];
344#NR:	return typeof fieldValue === "string" && fieldValue.length > 0
345#YT:		? fieldValue
346#TZ:		: undefined;
347#TZ:}
348#BQ:
349#RS:function omitUndefined<T extends Record<string, unknown>>(value: T): T {
350#XQ:	return Object.fromEntries(
351#MJ:		Object.entries(value).filter(([, entryValue]) => entryValue !== undefined),
352#JT:	) as T;
353#PZ:}
354#RR:
355#PW:function isRecord(value: unknown): value is Record<string, unknown> {
356#KH:	return typeof value === "object" && value !== null && !Array.isArray(value);
357#PX:}

