 2#XQ:import canonicalize from "canonicalize";
 3#HW:
 4#TZ:export type JsonPrimitive = string | number | boolean | null;
 5#NJ:export type JsonValue =
 6#TX:	| JsonPrimitive
 7#VB:	| JsonValue[]
 8#RS:	| { [key: string]: JsonValue };
 9#JT:
10#HW:export function canonicalJson(value: JsonValue): string {
11#JN:	validateJsonValue(value, "$", new Set());
12#TJ:	const serialized = canonicalize(value);
13#RW:	if (serialized === undefined) {
14#SR:		throw new TypeError("Value cannot be serialized as canonical JSON");
15#MT:	}
16#TB:	return serialized;
17#SH:}
18#KS:
19#RQ:export function canonicalJsonBytes(value: JsonValue): Uint8Array {
20#YW:	return Buffer.from(canonicalJson(value), "utf8");
21#MV:}
22#ZP:
23#JP:export function canonicalJsonSha256(value: JsonValue): string {
24#JS:	return createHash("sha256").update(canonicalJsonBytes(value)).digest("hex");
25#SR:}
26#HK:
27#TV:function validateJsonValue(
28#ZP:	value: unknown,
29#HY:	path: string,
30#BJ:	ancestors: Set<object>,
31#XR:): asserts value is JsonValue {
32#VY:	if (
33#PX:		value === null ||
34#HR:		typeof value === "string" ||
35#YV:		typeof value === "boolean"
36#YR:	) {
37#NV:		return;
38#ZW:	}
39#SM:	if (typeof value === "number") {
40#MR:		if (!Number.isFinite(value))
41#YR:			throw new TypeError(`Non-finite number at ${path}`);
42#JV:		if (Object.is(value, -0)) throw new TypeError(`Negative zero at ${path}`);
43#SS:		if (Number.isInteger(value) && !Number.isSafeInteger(value)) {
44#TZ:			throw new TypeError(`Unsafe integer at ${path}`);
45#ZM:		}
46#NV:		return;
47#QN:	}
48#WM:	if (typeof value !== "object" || value === undefined) {
49#SB:		throw new TypeError(`Unsupported JSON value at ${path}`);
50#ZP:	}
51#KV:	if (ancestors.has(value)) throw new TypeError(`Circular value at ${path}`);
52#QN:	ancestors.add(value);
53#WV:	if (Array.isArray(value)) {
54#VB:		for (const [index, child] of value.entries()) {
55#TQ:			validateJsonValue(child, `${path}[${index}]`, ancestors);
56#VJ:		}
57#TB:	} else {
58#QW:		const prototype = Object.getPrototypeOf(value);
59#VB:		if (prototype !== Object.prototype && prototype !== null) {
60#YP:			throw new TypeError(`Unsupported JSON object at ${path}`);
61#KV:		}
62#SJ:		for (const [key, child] of Object.entries(value)) {
63#PN:			validateJsonValue(child, `${path}.${key}`, ancestors);
64#XV:		}
65#KB:	}
66#RZ:	ancestors.delete(value);
67#PQ:}

