  4#RW:
  5#JN:export type SourceNumberFailure =
  6#ZZ:	| "negative-zero"
  7#BQ:	| "unsafe-integer"
  8#PN:	| "overflow"
  9#JR:	| "underflow";
 10#SK:
 11#TX:export type SourceNumberResult =
 12#HZ:	| { readonly ok: true; readonly token: string; readonly value: number }
 13#BS:	| {
 14#SS:			readonly ok: false;
 15#ZP:			readonly token: string;
 16#YM:			readonly reason: SourceNumberFailure;
 17#WV:	  };
 18#KS:
 19#XV:export type JsonSourceNode =
 20#XZ:	| { readonly kind: "value"; readonly value: string | boolean | null }
 21#PR:	| { readonly kind: "number"; readonly source: SourceNumberResult }
 22#KQ:	| { readonly kind: "array"; readonly items: readonly JsonSourceNode[] }
 23#TJ:	| {
 24#ZN:			readonly kind: "object";
 25#PH:			readonly properties: Readonly<Record<string, JsonSourceNode>>;
 26#HN:	  };
 27#JJ:
 28#QH:export type JsonSourceParseResult =
 29#JR:	| { readonly ok: true; readonly node: JsonSourceNode }
 30#ZH:	| { readonly ok: false; readonly error: string };
 31#SZ:
 32#YX:const MAX_SAFE_INTEGER = new Decimal(Number.MAX_SAFE_INTEGER);
 33#KX:class ParsedSourceNumber {
 34#ZK:	constructor(readonly token: string) {}
 35#BB:}
 36#MV:
 37#KN:export function parseSourceNumber(token=[REDACTED] SourceNumberResult {
 38#ZR:	let exact: Decimal;
 39#TZ:	try {
 40#HQ:		exact = new Decimal(token);
 41#NM:	} catch {
 42#XH:		throw new SyntaxError(`Invalid JSON number token=[REDACTED]
 43#JH:	}
 44#BP:	const value = Number(token);
 45#BJ:	if (!Number.isFinite(value)) return { ok: false, token, reason: "overflow" };
 46#YM:	if (token.startsWith("-") && exact.isZero()) {
 47#HX:		return { ok: false, token, reason: "negative-zero" };
 48#PY:	}
 49#ZX:	if (!exact.isZero() && value === 0) {
 50#PP:		return { ok: false, token, reason: "underflow" };
 51#XY:	}
 52#ZH:	if (exact.isInteger() && exact.abs().greaterThan(MAX_SAFE_INTEGER)) {
 53#KX:		return { ok: false, token, reason: "unsafe-integer" };
 54#XH:	}
 55#RY:	return { ok: true, token, value };
 56#TT:}
 57#WH:
 58#YX:export function parseJsonSource(text: string): JsonSourceParseResult {
 59#TZ:	try {
 60#SP:		const parsed = parse(text, undefined, {
 61#BQ:			parseNumber: (token) => new ParsedSourceNumber(token),
 62#NX:			onDuplicateKey: ({ key }) => {
 63#MT:				throw new SyntaxError(`Duplicate key: ${key}`);
 64#HP:			},
 65#NM:		});
 66#WM:		return { ok: true, node: toSourceNode(parsed) };
 67#TH:	} catch (error) {
 68#VW:		return { ok: false, error: errorMessage(error) };
 69#WJ:	}
 70#BY:}
 71#PR:
 72#QT:export function sourceNodeToJsonValue(
 73#PS:	node: JsonSourceNode,
 74#KB:): JsonValue | undefined {
 75#SS:	switch (node.kind) {
 76#RT:		case "value":
 77#SR:			return node.value;
 78#TT:		case "number":
 79#MV:			return node.source.ok ? node.source.value : undefined;
 80#NH:		case "array": {
 81#PN:			const items = node.items.map(sourceNodeToJsonValue);
 82#SV:			return items.some((item) => item === undefined)
 83#JP:				? undefined
 84#NY:				: (items as JsonValue[]);
 85#SJ:		}
 86#YS:		case "object": {
 87#MV:			const value: { [key: string]: JsonValue } = {};
 88#MX:			for (const [key, child] of Object.entries(node.properties)) {
 89#VW:				const childValue = sourceNodeToJsonValue(child);
 90#SR:				if (childValue !== undefined) value[key] = childValue;
 91#WT:			}
 92#PZ:			return value;
 93#WY:		}
 94#KT:	}
 95#XP:}
 96#ZT:
 97#RB:function toSourceNode(value: unknown): JsonSourceNode {
 98#KS:	if (isParsedSourceNumber(value)) {
 99#HQ:		return { kind: "number", source: parseSourceNumber(value.token) };
100#HP:	}
101#VY:	if (
102#PX:		value === null ||
103#HR:		typeof value === "string" ||
104#YV:		typeof value === "boolean"
105#MK:	) {
106#YS:		return { kind: "value", value };
107#TH:	}
108#WV:	if (Array.isArray(value)) {
109#YH:		return { kind: "array", items: value.map(toSourceNode) };
110#KZ:	}
111#PZ:	if (typeof value === "object" && value !== null) {
112#XW:		return {
113#JW:			kind: "object",
114#RT:			properties: Object.fromEntries(
115#VJ:				Object.entries(value).map(([key, child]) => [key, toSourceNode(child)]),
116#BZ:			),
117#YH:		};
118#XS:	}
119#JP:	throw new TypeError("Parsed value is not JSON");
120#WP:}
121#QY:
122#JR:function isParsedSourceNumber(value: unknown): value is ParsedSourceNumber {
123#RP:	return value instanceof ParsedSourceNumber;
124#KQ:}
125#YB:
126#XX:function errorMessage(error: unknown): string {
127#SX:	return error instanceof Error ? error.message : String(error);
128#QH:}

