266#TZ:		: undefined;
267#XT:}
268#RY:
269#WR:function numberField(
270#BM:	value: Record<string, unknown> | undefined,
271#JN:	field: string,
272#JP:): number | undefined {
273#KW:	const fieldValue = value?.[field];
274#KT:	if (typeof fieldValue === "number" && Number.isFinite(fieldValue)) {
275#NY:		return fieldValue;
276#NM:	}
277#PP:	if (typeof fieldValue === "string" && fieldValue.length > 0) {
278#VS:		const numericValue = Number(fieldValue);
279#ZN:		return Number.isFinite(numericValue) ? numericValue : undefined;
280#BH:	}
281#TM:	return undefined;
282#XP:}
283#RS:
284#YJ:function booleanField(
285#BM:	value: Record<string, unknown> | undefined,
286#JN:	field: string,
287#XY:): boolean | undefined {
288#KW:	const fieldValue = value?.[field];
289#KM:	return typeof fieldValue === "boolean" ? fieldValue : undefined;
290#RJ:}
291#BV:
292#RS:function omitUndefined<T extends Record<string, unknown>>(value: T): T {
293#XQ:	return Object.fromEntries(
294#MJ:		Object.entries(value).filter(([, entryValue]) => entryValue !== undefined),
295#JT:	) as T;
296#TB:}
297#QN:
298#PW:function isRecord(value: unknown): value is Record<string, unknown> {
299#KH:	return typeof value === "object" && value !== null && !Array.isArray(value);
300#TP:}

