  3#HH:export type TranscriptVisibleKind =
  4#BK:	| "user-text"
  5#RM:	| "assistant-text"
  6#YS:	| "reasoning"
  7#WY:	| "attachment"
  8#WT:	| "image"
  9#VJ:	| "tool-execution"
 10#BP:	| "standalone-tool-result"
 11#MW:	| "compaction"
 12#WM:	| "response-boundary";
 13#BQ:
 14#MQ:export type RecordProjectionColumns = {
 15#WJ:	readonly ownerRecordId?: string;
 16#MR:	readonly callRecordId?: string;
 17#NQ:	readonly diagnosticOwnerKind?: "record" | "turn";
 18#HK:	readonly diagnosticOwnerRecordId?: string;
 19#KZ:	readonly diagnosticOwnerTurnId?: string;
 20#RH:	readonly transcriptVisibleKind?: TranscriptVisibleKind;
 21#VP:	readonly transcriptOwnerOrdinal?: string;
 22#RV:};
 23#NV:
 24#MT:export type RecordRelationSource = {
 25#KY:	readonly canonicalRevisionId: string;
 26#NK:	readonly records: readonly canonicalV2.CanonicalRecord[];
 27#RN:	readonly turns: readonly canonicalV2.CanonicalTurnRef[];
 28#HK:	readonly projectionColumns?: ReadonlyMap<string, RecordProjectionColumns>;
 29#VM:};
 30#ZM:
 31#WM:export type ValidatedRecordRelations = {
 32#VQ:	readonly projectionColumns: ReadonlyMap<string, RecordProjectionColumns>;
 33#BS:};
 34#WV:
 35#RB:export function validateRecordRelations(
 36#KX:	source: RecordRelationSource,
 37#KT:): ValidatedRecordRelations {
 38#YZ:	const records = uniqueBy(
 39#ZK:		source.records,
 40#TT:		(record) => record.recordId,
 41#QN:		"record",
 42#TK:	);
 43#JM:	const turns = uniqueBy(source.turns, (turn) => turn.turnId, "turn");
 44#SH:	validateRevisionIdentity(source, records, turns);
 45#JK:	validateTurns(records, turns);
 46#TJ:
 47#YM:	const resultsByCall = new Map<string, canonicalV2.CanonicalRecord>();
 48#KB:	for (const record of source.records)
 49#VJ:		validateDirectRelations(record, records, turns, resultsByCall);
 50#QJ:	validateTurnParents(turns);
 51#PZ:
 52#JN:	const projectionColumns = buildProjectionColumns(
 53#ZK:		source.records,
 54#BS:		records,
 55#NT:		turns,
 56#BN:	);
 57#KX:	if (source.projectionColumns !== undefined) {
 58#WP:		for (const record of source.records) {
 59#VK:			assertColumnsEqual(
 60#MT:				record.recordId,
 61#XV:				source.projectionColumns.get(record.recordId),
 62#QZ:				projectionColumns.get(record.recordId),
 63#KX:			);
 64#XV:		}
 65#SZ:		for (const recordId of source.projectionColumns.keys()) {
 66#RB:			if (!records.has(recordId))
 67#PW:				fail(`Projection columns reference unknown record ${recordId}.`);
 68#BV:		}
 69#WJ:	}
 70#PY:	return { projectionColumns };
 71#JV:}
 72#SV:
 73#NV:function validateRevisionIdentity(
 74#KX:	source: RecordRelationSource,
 75#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
 76#QV:	turns: ReadonlyMap<string, canonicalV2.CanonicalTurnRef>,
 77#XJ:): void {
 78#BH:	for (const record of records.values()) {
 79#PZ:		if (record.canonicalRevisionId !== source.canonicalRevisionId)
 80#XJ:			fail(`Record ${record.recordId} belongs to a different revision.`);
 81#ZJ:	}
 82#MK:	for (const turn of turns.values()) {
 83#YZ:		if (turn.canonicalRevisionId !== source.canonicalRevisionId)
 84#XH:			fail(`Turn ${turn.turnId} belongs to a different revision.`);
 85#ZW:	}
 86#HS:}
 87#XB:
 88#RV:function validateTurns(
 89#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
 90#QV:	turns: ReadonlyMap<string, canonicalV2.CanonicalTurnRef>,
 91#XJ:): void {
 92#ST:	const anchors = new Set<string>();
 93#MK:	for (const turn of turns.values()) {
 94#YV:		const anchor = requireRecord(
 95#QR:			records,
 96#TT:			turn.assistantResponseRecordId,
 97#YS:			`turn ${turn.turnId} anchor`,
 98#KH:		);
 99#ZV:		if (anchor.kind !== "assistant-response" || anchor.turnId !== turn.turnId)
100#JW:			fail(`Turn ${turn.turnId} has an invalid assistant response anchor.`);
101#MX:		if (anchor.globalOrdinal !== turn.startOrdinal)
102#RH:			fail(`Turn ${turn.turnId} startOrdinal does not match its anchor.`);
103#ZS:		if (anchors.has(anchor.recordId))
104#XN:			fail(`Assistant response ${anchor.recordId} anchors multiple turns.`);
105#MX:		anchors.add(anchor.recordId);
106#BH:		if (turn.inputRecordId !== undefined) {
107#SV:			const input = requireRecord(
108#NZ:				records,
109#MZ:				turn.inputRecordId,
110#ZQ:				`turn ${turn.turnId} input`,
111#BQ:			);
112#RN:			if (input.kind !== "message-boundary")
113#TN:				fail(`Turn ${turn.turnId} input is not a message boundary.`);
114#WM:		}
115#WY:	}
116#BH:	for (const record of records.values()) {
117#XZ:		if (record.turnId !== undefined && !turns.has(record.turnId))
118#XQ:			fail(`Record ${record.recordId} names unknown turn ${record.turnId}.`);
119#RB:		if (record.kind === "assistant-response" && !anchors.has(record.recordId))
120#HR:			fail(`Assistant response ${record.recordId} does not anchor a turn.`);
121#MK:	}
122#PT:}
123#WY:
124#VM:function validateDirectRelations(
125#PS:	record: canonicalV2.CanonicalRecord,
126#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
127#QV:	turns: ReadonlyMap<string, canonicalV2.CanonicalTurnRef>,
128#BT:	resultsByCall: Map<string, canonicalV2.CanonicalRecord>,
129#XJ:): void {
130#KP:	const payload = record.payload;
131#YJ:	if ("ownerRecordId" in payload) {
132#VR:		const owner = requireRecord(
133#QR:			records,
134#KX:			payload.ownerRecordId,
135#KK:			`${record.recordId} owner`,
136#RW:		);
137#BV:		const allowed = ownerKinds(payload.kind);
138#RN:		if (!allowed.includes(owner.kind))
139#MM:			fail(`${record.recordId} has wrong owner kind ${owner.kind}.`);
140#YX:		if (payload.kind === "text-content" && owner.kind === "message-boundary") {
141#WW:			if (record.turnId !== undefined)
142#NY:				fail(`Boundary-owned text ${record.recordId} must omit turnId.`);
143#XN:		} else if (owner.turnId === undefined) {
144#WW:			if (record.turnId !== undefined)
145#ZH:				fail(
146#PQ:					`${record.recordId} must omit turnId with owner ${owner.recordId}.`,
147#BH:				);
148#NS:		} else if (record.turnId !== owner.turnId) {
149#QT:			fail(`${record.recordId} and owner ${owner.recordId} must share a turn.`);
150#TT:		}
151#ZZ:	}
152#JK:	if (payload.kind === "tool-result") {
153#VT:		if ("callRecordId" in payload) {
154#VK:			const call = requireRecord(
155#NZ:				records,
156#XB:				payload.callRecordId,
157#HR:				`${record.recordId} call`,
158#VM:			);
159#NW:			if (call.kind !== "tool-call")
160#WR:				fail(`${record.recordId} call target is not a tool call.`);
161#QP:			if (record.turnId === undefined || record.turnId !== call.turnId)
162#SZ:				fail(`${record.recordId} and call ${call.recordId} must share a turn.`);
163#RY:			if (resultsByCall.has(call.recordId))
164#BX:				fail(`Tool call ${call.recordId} has multiple results.`);
165#WT:			resultsByCall.set(call.recordId, record);
166#WJ:		}
167#TS:		for (const attachmentId of payload.attachments) {
168#JM:			const attachment = requireRecord(
169#NZ:				records,
170#MJ:				attachmentId,
171#RR:				`${record.recordId} attachment`,
172#NN:			);
173#YX:			if (
174#KX:				attachment.kind !== "attachment" ||
175#JK:				attachment.payload.kind !== "attachment" ||
176#SS:				attachment.payload.ownerRecordId !== record.recordId
177#TT:			)
178#ZH:				fail(
179#JN:					`Tool result ${record.recordId} has an invalid attachment ${attachmentId}.`,
180#ZY:				);
181#QS:		}
182#PH:	}
183#PV:	if (payload.kind === "diagnostic") {
184#KR:		if (payload.owner?.kind === "record")
185#SM:			requireRecord(
186#NZ:				records,
187#WV:				payload.owner.recordId,
188#NB:				`${record.recordId} diagnostic owner`,
189#KW:			);
190#ZH:		if (payload.owner?.kind === "turn" && !turns.has(payload.owner.turnId))
191#QQ:			fail(
192#RJ:				`Diagnostic ${record.recordId} names unknown turn ${payload.owner.turnId}.`,
193#JN:			);
194#WJ:		const related = payload.relatedRecordIds ?? [];
195#QX:		if (new Set(related).size !== related.length)
196#HP:			fail(`Diagnostic ${record.recordId} has duplicate related records.`);
197#TT:		for (const relatedId of related)
198#SM:			requireRecord(
199#NZ:				records,
200#ZV:				relatedId,
201#RY:				`${record.recordId} diagnostic relation`,
202#MH:			);
203#JS:		const ordered = [...related].sort((left, right) =>
204#KQ:			compareRecordOrder(
205#SR:				requireRecord(records, left, "diagnostic relation"),
206#TK:				requireRecord(records, right, "diagnostic relation"),
207#YW:			),
208#VX:		);
209#ZS:		if (ordered.some((value, index) => value !== related[index]))
210#QQ:			fail(
211#YS:				`Diagnostic ${record.recordId} related records are not in canonical order.`,
212#PB:			);
213#WZ:	}
214#HW:}
215#XJ:
216#PY:function buildProjectionColumns(
217#BM:	all: readonly canonicalV2.CanonicalRecord[],
218#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
219#QV:	turns: ReadonlyMap<string, canonicalV2.CanonicalTurnRef>,
220#YR:): ReadonlyMap<string, RecordProjectionColumns> {
221#NM:	const visibleInTurn = new Set<string>();
222#XV:	const columns = new Map<string, RecordProjectionColumns>();
223#TR:	for (const record of all) {
224#VK:		const payload = record.payload;
225#NR:		const direct = directColumns(payload);
226#WP:		let visible = visibleKind(record, records);
227#QH:		let ownerOrdinal = visible === undefined ? undefined : record.globalOrdinal;
228#JP:		if (payload.kind === "tool-result" && "callRecordId" in payload) {
229#KS:			visible = "tool-execution";
230#NS:			ownerOrdinal = requireRecord(
231#NZ:				records,
232#XB:				payload.callRecordId,
233#ZX:				`${record.recordId} tool call`,
234#NN:			).globalOrdinal;
235#YV:		}
236#JJ:		if (visible !== undefined && record.turnId !== undefined)
237#XJ:			visibleInTurn.add(record.turnId);
238#MN:		columns.set(record.recordId, {
239#BH:			...direct,
240#NJ:			...(visible === undefined
241#BX:				? {}
242#RV:				: {
243#NZ:						transcriptVisibleKind: visible,
244#HT:						transcriptOwnerOrdinal: ownerOrdinal,
245#SN:					}),
246#JV:		});
247#RZ:	}
248#MK:	for (const turn of turns.values()) {
249#PQ:		if (visibleInTurn.has(turn.turnId)) continue;
250#YV:		const anchor = requireRecord(
251#QR:			records,
252#TT:			turn.assistantResponseRecordId,
253#ZS:			`${turn.turnId} assistant response`,
254#KY:		);
255#RB:		columns.set(anchor.recordId, {
256#TY:			transcriptVisibleKind: "response-boundary",
257#ZJ:			transcriptOwnerOrdinal: anchor.globalOrdinal,
258#TV:		});
259#ZS:	}
260#YN:	return columns;
261#PV:}
262#XB:
263#RP:function directColumns(
264#SK:	payload: canonicalV2.CanonicalPayload,
265#BH:): RecordProjectionColumns {
266#HK:	if ("ownerRecordId" in payload)
267#TZ:		return { ownerRecordId: payload.ownerRecordId };
268#QR:	if (payload.kind === "tool-result" && "callRecordId" in payload)
269#WY:		return { callRecordId: payload.callRecordId };
270#JB:	if (payload.kind === "diagnostic" && payload.owner !== undefined)
271#YN:		return payload.owner.kind === "record"
272#KQ:			? {
273#QN:					diagnosticOwnerKind: "record",
274#TJ:					diagnosticOwnerRecordId: payload.owner.recordId,
275#YV:				}
276#BY:			: {
277#PT:					diagnosticOwnerKind: "turn",
278#NN:					diagnosticOwnerTurnId: payload.owner.turnId,
279#RR:				};
280#WQ:	return {};
281#PT:}
282#QT:
283#JT:function visibleKind(
284#PS:	record: canonicalV2.CanonicalRecord,
285#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
286#QJ:): TranscriptVisibleKind | undefined {
287#KP:	const payload = record.payload;
288#WV:	switch (payload.kind) {
289#SV:		case "text-content": {
290#VV:			const owner = requireRecord(
291#NZ:				records,
292#ZT:				payload.ownerRecordId,
293#QH:				`${record.recordId} text owner`,
294#JQ:			);
295#QX:			return owner.kind === "message-boundary" &&
296#PH:				owner.payload.kind === "message-boundary" &&
297#QQ:				owner.payload.role === "user"
298#WR:				? "user-text"
299#YW:				: owner.kind === "assistant-response"
300#QT:					? "assistant-text"
301#YW:					: undefined;
302#PX:		}
303#TX:		case "reasoning-content":
304#TS:			return "reasoning";
305#ZV:		case "tool-call":
306#XB:			return "tool-execution";
307#SK:		case "tool-result":
308#JX:			return "callRecordId" in payload ? undefined : "standalone-tool-result";
309#PK:		case "attachment":
310#JY:			return payload.mediaType.startsWith("image/") ? "image" : "attachment";
311#NQ:		case "compaction":
312#XW:			return "compaction";
313#NB:		default:
314#WH:			return undefined;
315#WH:	}
316#RZ:}
317#MM:
318#RS:function ownerKinds(
319#VQ:	kind: canonicalV2.CanonicalPayload["kind"],
320#TS:): readonly canonicalV2.CanonicalRecord["kind"][] {
321#WH:	switch (kind) {
322#ZV:		case "text-content":
323#BB:			return ["message-boundary", "assistant-response"];
324#TX:		case "reasoning-content":
325#ZV:		case "tool-call":
326#MS:		case "usage":
327#QH:			return ["assistant-response"];
328#PK:		case "attachment":
329#WY:			return ["message-boundary", "assistant-response", "tool-result"];
330#NB:		default:
331#SS:			return [];
332#ZB:	}
333#VP:}
334#RY:
335#YQ:function validateTurnParents(
336#QV:	turns: ReadonlyMap<string, canonicalV2.CanonicalTurnRef>,
337#XJ:): void {
338#MK:	for (const turn of turns.values()) {
339#TH:		const seen = new Set([turn.turnId]);
340#JZ:		let parentId = turn.parentTurnId;
341#ZQ:		while (parentId !== undefined) {
342#WR:			const parent = turns.get(parentId);
343#VP:			if (parent === undefined)
344#ZP:				fail(`Turn ${turn.turnId} names unknown parent ${parentId}.`);
345#KK:			if (seen.has(parentId))
346#HW:				fail(`Turn ancestry contains a cycle at ${parentId}.`);
347#RY:			seen.add(parentId);
348#QB:			parentId = parent.parentTurnId;
349#MH:		}
350#RP:	}
351#YM:}
352#NX:
353#SZ:function assertColumnsEqual(
354#NJ:	recordId: string,
355#NN:	actual: RecordProjectionColumns | undefined,
356#RB:	expected: RecordProjectionColumns | undefined,
357#XJ:): void {
358#ZV:	if (JSON.stringify(actual ?? {}) !== JSON.stringify(expected ?? {}))
359#ZW:		fail(`Record ${recordId} has invalid projection columns.`);
360#JH:}
361#BR:
362#BB:function requireRecord(
363#RT:	records: ReadonlyMap<string, canonicalV2.CanonicalRecord>,
364#HQ:	id: string,
365#ZM:	relation: string,
366#XH:): canonicalV2.CanonicalRecord {
367#NM:	const record = records.get(id);
368#WZ:	if (record === undefined) fail(`Dangling ${relation}: ${id}.`);
369#YY:	return record;
370#VM:}
371#MZ:
372#QN:function uniqueBy<T>(
373#RP:	values: readonly T[],
374#ZT:	key: (value: T) => string,
375#JN:	label: string,
376#KW:): ReadonlyMap<string, T> {
377#TJ:	const result = new Map<string, T>();
