121#XW:		}
122#YM:	}
123#TN:	const parsed = schema.safeParse(decoded);
124#HV:	if (!parsed.success)
125#ZS:		fail(
126#MS:			`Invalid persisted ${label}: ${parsed.error.issues[0]?.message ?? "schema mismatch"}`,
127#RR:		);
