256#WV:## Rollback Strategies
257#BK:
258#QS:### Transaction-Based Migrations
259#WQ:
260#XH:```javascript
261#XP:module.exports = {
262#BW:  up: async (queryInterface, Sequelize) => {
263#BS:    const transaction = await queryInterface.sequelize.transaction();
264#BP:
265#VN:    try {
266#WS:      await queryInterface.addColumn(
267#HW:        "users",
268#TZ:        "verified",
269#WR:        { type: Sequelize.BOOLEAN, defaultValue: false },
270#VT:        { transaction },
271#SJ:      );
272#NM:
273#KW:      await queryInterface.sequelize.query(
274#PT:        "UPDATE users SET verified = true WHERE email_verified_at IS NOT NULL",
275#VT:        { transaction },
276#XP:      );
277#WQ:
278#QW:      await transaction.commit();
279#SH:    } catch (error) {
280#YH:      await transaction.rollback();
281#HR:      throw error;
282#VB:    }
283#BN:  },
284#XQ:
285#MR:  down: async (queryInterface) => {
286#WX:    await queryInterface.removeColumn("users", "verified");
287#JJ:  },
288#NJ:};
289#QW:```
290#YM:
291#PJ:### Checkpoint-Based Rollback
292#RT:
293#XH:```javascript
294#XP:module.exports = {
295#BW:  up: async (queryInterface, Sequelize) => {
296#WW:    // Create backup table
297#QV:    await queryInterface.sequelize.query(
298#WP:      "CREATE TABLE users_backup AS SELECT * FROM users",
299#KV:    );
300#NX:
301#VN:    try {
302#RN:      // Perform migration
303#YN:      await queryInterface.addColumn("users", "new_field", {
304#JR:        type: Sequelize.STRING,
305#HH:      });
306#PN:
307#MR:      // Verify migration
308#ZZ:      const [result] = await queryInterface.sequelize.query(
309#RK:        "SELECT COUNT(*) as count FROM users WHERE new_field IS NULL",
310#ZY:      );
311#RN:
312#HM:      if (result[0].count > 0) {
313#KJ:        throw new Error("Migration verification failed");
314#XP:      }
315#TH:
316#ZH:      // Drop backup
317#VK:      await queryInterface.dropTable("users_backup");
318#SH:    } catch (error) {
319#KZ:      // Restore from backup
320#JW:      await queryInterface.sequelize.query("DROP TABLE users");
321#KW:      await queryInterface.sequelize.query(
322#VJ:        "CREATE TABLE users AS SELECT * FROM users_backup",
323#QB:      );
324#VK:      await queryInterface.dropTable("users_backup");
325#HR:      throw error;
326#BY:    }
327#MT:  },
328#KX:};
329#KQ:```
