 58#RP:export function decodeCursor(cursor: string): CursorPayload {
 59#SZ:	let parsed: unknown;
 60#TZ:	try {
 61#XW:		parsed = JSON.parse(Buffer.from(cursor, "base64url").toString("utf8"));
 62#NM:	} catch {
 63#JK:		throw new InvalidCursorError("Invalid cursor: malformed encoding");
 64#SV:	}
 65#VY:	if (
 66#WZ:		typeof parsed !== "object" ||
 67#XB:		parsed === null ||
 68#MS:		typeof (parsed as Record<string, unknown>).ingestedAt !== "string" ||
 69#WN:		typeof (parsed as Record<string, unknown>).id !== "string"
 70#WK:	) {
 71#VQ:		throw new InvalidCursorError("Invalid cursor: missing required fields");
 72#NM:	}
 73#RQ:	return parsed as CursorPayload;
