 95#YS:function projectRecordFinding(
 96#PS:	record: canonicalV2.CanonicalRecord,
 97#SH:	identity: AnalyticsEvidenceIdentityDto,
 98#BP:): OrderedFinding {
 99#KP:	const payload = record.payload;
100#WV:	switch (payload.kind) {
101#PM:		case "diagnostic":
102#WZ:			return recordFinding(record, identity, {
103#KP:				id: `${record.recordId}:diagnostic:${payload.code}`,
104#PM:				severity: "warning",
105#VM:				category: "diagnostic",
106#YP:				type: payload.code,
107#WY:				reason: boundedReason(payload.message),
108#MY:			});
109#SK:		case "tool-result":
110#WM:			if (payload.outcome !== "failed") break;
111#WZ:			return recordFinding(record, identity, {
112#NK:				id: `${record.recordId}:failed-tool`,
113#MP:				severity: "error",
114#BR:				category: "tool",
115#XV:				type: "failed_tool",
116#JT:				reason: "Canonical tool result reported failure.",
117#ZW:			});
118#NB:		case "assistant-response": {
119#ZJ:			const termination = payload.termination;
120#YX:			if (
121#PM:				termination === undefined ||
122#MM:				termination.kind === "completed" ||
123#WS:				termination.kind === "tool-use"
