127#NK:			const reason =
128#BR:				termination.kind === "error" && termination.message !== undefined
129#QP:					? boundedReason(termination.message)
130#MT:					: assistantTerminationReason(termination.kind);
131#WZ:			return recordFinding(record, identity, {
132#NJ:				id: `${record.recordId}:assistant-${termination.kind}`,
133#SW:				severity,
134#QM:				category: "assistant",
135#JW:				type: `assistant_${termination.kind}`,
136#QJ:				reason,
137#TH:			});
138#QT:		}
