130#SQ:): AnalyticsGraphEdgeDto {
131#WT:	const id = `${relation.targetRecordId}:${relation.relation}:${record.recordId}`;
132#XX:	return {
133#XZ:		id,
134#JQ:		sourceId: relation.targetRecordId,
135#JP:		targetId: record.recordId,
136#WZ:		relation: relation.relation,
137#HM:		directed: true,
138#QR:		evidence: [projectEvidence(record, identity, `${id}:evidence`)],
139#NT:		attributes: { canonicalRecordId: record.recordId },
140#ZJ:	};
141#JJ:}
142#HQ:
143#KK:function projectEvidence(
144#PV:	record: CanonicalV2GraphRecord,
145#SH:	identity: AnalyticsEvidenceIdentityDto,
146#HQ:	id: string,
147#YY:): AnalyticsEvidenceRefDto {
148#JZ:	const evidence = record.evidence[0];
149#NT:	if (evidence === undefined)
150#YY:		throw new TypeError("Canonical-v2 graph record is missing evidence.");
151#XX:	return {
152#XZ:		id,
153#RK:		identity: { ...identity, rawArtifactId: evidence.artifactId },
154#WV:		source: {
155#VH:			line: evidenceLine(evidence, record.globalOrdinal),
156#VV:			canonicalRecordId: record.recordId,
157#NT:		},
158#WQ:		label: "Canonical graph relation evidence",
159#NR:	};
160#TX:}
161#JB:
162#PT:function evidenceLine(
163#QB:	evidence: canonicalV2.EvidenceRef,
164#NN:	globalOrdinal: string,
165#MN:): number {
166#KX:	if (evidence.locator.kind === "text-range") {
167#XR:		const coordinates = evidence.locator.coordinates;
168#ZP:		if (coordinates.kind !== "byte") return coordinates.lineRange.start;
169#VP:	}
170#HH:	if (evidence.locator.kind === "sequence-range")
171#BY:		return boundedPositiveInteger(evidence.locator.start);
172#XZ:	return boundedPositiveInteger(globalOrdinal);
173#BN:}
174#RT:
175#MB:function boundedPositiveInteger(value: string): number {
176#MK:	const parsed = BigInt(value);
177#NY:	return parsed > 0n && parsed <= BigInt(Number.MAX_SAFE_INTEGER)
178#MK:		? Number(parsed)
179#YQ:		: 1;
180#PM:}
181#WS:
182#KZ:function recordLabel(kind: canonicalV2.CanonicalKind): string {
183#XQ:	return kind
184#QY:		.split("-")
185#KS:		.map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
186#YV:		.join(" ");
187#VX:}
188#XH:
189#YJ:function cap(
190#RX:	requested: number,
191#RW:	applied: number,
192#MB:	maximum: number,
193#MR:	returned: number,
194#SN:	total: number,
195#KS:) {
196#QK:	const hidden = total - returned;
197#XX:	return {
198#HK:		capped: true as const,
199#MS:		requested,
200#WZ:		applied,
201#QR:		maximum,
202#BP:		returned,
203#TJ:		total,
204#YS:		hidden,
205#KY:		truncated: hidden > 0,
206#HW:	};
207#RT:}
208#NZ:
209#TP:function assertInput(
210#BB:	input: CanonicalV2GraphProjectionInput,
211#NN:	appliedNodeLimit: number,
212#YY:	appliedEdgeLimit: number,
213#XJ:): void {
214#YN:	for (const [label, value] of [
215#ZN:		["requested node limit", input.requestedNodeLimit],
216#WX:		["requested edge limit", input.requestedEdgeLimit],
217#KN:		["applied node limit", appliedNodeLimit],
218#XW:		["applied edge limit", appliedEdgeLimit],
219#SK:	] as const) {
220#BR:		if (!Number.isSafeInteger(value) || value < 1)
221#RY:			throw new TypeError(`Canonical-v2 graph ${label} is invalid.`);
222#SS:	}
223#VY:	if (
224#VV:		!Number.isSafeInteger(input.totalNodeCount) ||
225#YQ:		input.totalNodeCount < input.records.length ||
226#NY:		input.records.length !== Math.min(input.totalNodeCount, appliedNodeLimit)
227#XW:	)
228#SJ:		throw new TypeError("Canonical-v2 graph node window is inconsistent.");
229#RX:	if (!Number.isSafeInteger(input.totalEdgeCount) || input.totalEdgeCount < 0)
230#HJ:		throw new TypeError("Canonical-v2 graph edge total is invalid.");
231#SV:}

